sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float angle;
uniform float spread;
uniform float amplitude;
uniform float frequency;
uniform float phase;
uniform float speed;
uniform float amount;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float a = radians(angle);
    float2 d = float2(cos(a), sin(a));
    float2 n = float2(-d.y, d.x);
    float4 acc = float4(0.0);
    for (int i = 0; i < 16; i++) {
        float t = float(i) / 15.0 - 0.5;
        float w = sin(t * frequency * 6.2831853 + radians(phase) + time * speed) * amplitude;
        acc += tex(coord + d * t * spread + n * w);
    }
    return fin(c, mix(c, acc / 16.0, amount), opacity);
}
